HyperbolicBoids.customGLSL:
// @node hyperbolicBoids
// @title Hyperbolic Boids
// @category custom
// @description Renders the H3 flock: rays are geodesics gamma(s) = cosh(s) p + sinh(s) v from the sim's orbit camera. Each pixel culls boids with its screen tile's bitmasks and the projected screen boxes, then sphere-traces the candidates' bird SDFs in their own normal coordinates (log map at the boid, frame = heading / banked up / side). Iridescent thin-film shading lit from an ideal point, compact hyperbolic halos, the trails from the Boid Trails canvas (dimmed behind birds), the {4,3,5} honeycomb (walked by Lorentz reflections from the camera folded into the base cell) as faint wires with vertex sparks, fog by hyperbolic distance, and the ideal boundary (stars, nebula, the light's sun) at the end of every ray. music = level-gated drive: kicks flash the spines, eyes, halos, trails and lattice vertices. Returns HDR color.
// ---- H3 helpers, hyperboloid model: <a,b> = a.x b.x + a.y b.y + a.z b.z - a.w b.w, <p,p> = -1 ----
float br_dot(vec4 a, vec4 b) {
    return dot(a.xyz, b.xyz) - a.w * b.w;
}

// Back onto the upper sheet of the hyperboloid
vec4 br_toH(vec4 p) {
    return p / sqrt(max(-br_dot(p, p), 1e-12));
}

// Tangent projection at p
vec4 br_tan(vec4 v, vec4 p) {
    return v + br_dot(v, p) * p;
}

vec4 br_unit(vec4 v) {
    return v * inversesqrt(max(br_dot(v, v), 1e-14));
}

float br_acosh(float c) {
    c = max(c, 1.0);
    return log(c + sqrt(c * c - 1.0));
}

float br_asinh(float x) {
    return log(x + sqrt(x * x + 1.0));
}

// Log map: tangent vector at p pointing to q, length = d(p, q)
vec4 br_log(vec4 p, vec4 q) {
    float c = max(-br_dot(p, q), 1.0);
    float sh = sqrt(c * c - 1.0);
    if (sh < 1e-7) return vec4(0.0);
    return (q - c * p) * (log(c + sh) / sh);
}

// Exponential map: walk the geodesic from p with initial velocity v for |v|
vec4 br_exp(vec4 p, vec4 v) {
    float n = sqrt(max(br_dot(v, v), 0.0));
    if (n < 1e-8) return p;
    return cosh(n) * p + (sinh(n) / n) * v;
}

// Parallel transport of w (tangent at q) along the geodesic q -> p
vec4 br_transport(vec4 w, vec4 q, vec4 p) {
    return w + br_dot(p, w) / (1.0 - br_dot(q, p)) * (q + p);
}

// Lorentz-orthogonal complement of three vectors (generalized cross product, index lowered)
vec4 br_cross4(vec4 a, vec4 b, vec4 c) {
    float x = dot(a.yzw, cross(b.yzw, c.yzw));
    float y = -dot(a.xzw, cross(b.xzw, c.xzw));
    float z = dot(a.xyw, cross(b.xyw, c.xyw));
    float w = -dot(a.xyz, cross(b.xyz, c.xyz));
    return vec4(x, y, z, -w);
}

vec3 br_hash3(uvec3 v) {
    v = v * 1664525u + 1013904223u;
    v.x += v.y * v.z; v.y += v.z * v.x; v.z += v.x * v.y;
    v ^= v >> 16u;
    v.x += v.y * v.z; v.y += v.z * v.x; v.z += v.x * v.y;
    return vec3(v) * (1.0 / 4294967296.0);
}

// Outward unit normal of face k of the {4,3,5} base cell (Klein cube |x_j| <= A)
vec4 br_face(int k) {
    const float A = 0.48586827;
    int j = k / 2;
    float s = (k - j * 2 == 0) ? 1.0 : -1.0;
    vec3 e = j == 0 ? vec3(1.0, 0.0, 0.0) : (j == 1 ? vec3(0.0, 1.0, 0.0) : vec3(0.0, 0.0, 1.0));
    return vec4(e * s, A) * 1.1441228;   // 1 / sqrt(1 - A^2)
}

// Three-colour cyclic palette
vec3 br_pal(float t, vec3 a, vec3 b, vec3 c) {
    t = fract(t) * 3.0;
    if (t < 1.0) return mix(a, b, smoothstep(0.0, 1.0, t));
    if (t < 2.0) return mix(b, c, smoothstep(1.0, 2.0, t));
    return mix(c, a, smoothstep(2.0, 3.0, t));
}


// Bird SDF in body units (x forward, y up, z side). part: 0 body, 1 wing, 2 tail, 3 head
float br_ellipsoid(vec3 p, vec3 r) {
    float k0 = length(p / r);
    float k1 = length(p / (r * r));
    return k0 * (k0 - 1.0) / max(k1, 1e-6);
}

float br_roundCone(vec3 p, vec3 a, vec3 b, float r1, float r2) {
    vec3 ba = b - a;
    float l2 = dot(ba, ba);
    float rr = r1 - r2;
    float a2 = l2 - rr * rr;
    float il2 = 1.0 / l2;
    vec3 pa = p - a;
    float y = dot(pa, ba);
    float z = y - l2;
    vec3 xv = pa * l2 - ba * y;
    float x2 = dot(xv, xv);
    float y2 = y * y * l2;
    float z2 = z * z * l2;
    float k = sign(rr) * rr * rr * x2;
    if (sign(z) * a2 * z2 > k) return sqrt(x2 + z2) * il2 - r2;
    if (sign(y) * a2 * y2 < k) return sqrt(x2 + y2) * il2 - r1;
    return (sqrt(x2 * a2 * il2) + y * rr) * il2 - r1;
}

float br_smin(float a, float b, float k, out float h) {
    h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
    return mix(b, a, h) - k * h * (1.0 - h);
}

float br_bird(vec3 p, float phase, float amp, float span, out float part) {
    float h;
    float body = br_roundCone(p, vec3(-0.30, 0.0, 0.0), vec3(0.17, 0.012, 0.0), 0.026, 0.07);
    float head = length(p - vec3(0.25, 0.028, 0.0)) - 0.056;
    float d = br_smin(body, head, 0.05, h);
    part = h > 0.5 ? 0.0 : 3.0;
    // wings (mirrored): arm + hand, rotated about the body axis by the flap angle; the hand lags
    float fl = amp * sin(phase);
    vec3 q = vec3(p.x - 0.04, p.y - 0.02, abs(p.z) - 0.025);
    float c = cos(fl), s = sin(fl);
    q = vec3(q.x, c * q.y - s * q.z, s * q.y + c * q.z);
    q.x += 0.3 * q.z;
    float arm = br_ellipsoid(q - vec3(-0.01, 0.0, 0.15 * span), vec3(0.125, 0.016, 0.17 * span));
    vec3 k = q - vec3(-0.03, 0.0, 0.3 * span);
    float fl2 = 0.6 * amp * sin(phase - 1.0);
    k = vec3(k.x, cos(fl2) * k.y - sin(fl2) * k.z, sin(fl2) * k.y + cos(fl2) * k.z);
    k.x += 0.35 * k.z;
    float hand = br_ellipsoid(k - vec3(-0.02, 0.0, 0.13 * span), vec3(0.075, 0.011, 0.17 * span));
    float wing = br_smin(arm, hand, 0.03, h);
    float dw = br_smin(wing, d, 0.04, h);
    if (h > 0.5) part = 1.0;
    d = dw;
    // forked tail
    vec3 t = p - vec3(-0.30, 0.0, 0.0);
    vec2 tz = vec2(t.x, abs(t.z));
    tz = vec2(0.955 * tz.x + 0.296 * tz.y, -0.296 * tz.x + 0.955 * tz.y);
    float tail = br_ellipsoid(vec3(tz.x + 0.13, t.y, tz.y), vec3(0.15, 0.009, 0.03));
    float dt = br_smin(tail, d, 0.035, h);
    if (h > 0.5) part = 2.0;
    return dt;
}

// Sky: the ideal boundary point of the geodesic (p, v) is the null vector p + v
vec3 br_sky(vec4 p, vec4 v, vec3 a, vec3 b, vec3 sunDir, vec3 sunCol) {
    vec4 e = p + v;
    vec3 xi = e.xyz / max(e.w, 1e-6);
    vec3 col = vec3(0.004, 0.006, 0.016) + vec3(0.006, 0.010, 0.022) * (1.0 - abs(xi.y));
    float nb = sin(xi.x * 3.1 + sin(xi.z * 4.3 + xi.y * 2.0)) * sin(xi.z * 2.7 - xi.y * 3.3 + sin(xi.x * 5.1));
    float nb2 = sin(xi.x * 7.3 - xi.z * 6.1 + xi.y * 4.0 + nb * 2.0) * 0.5 + 0.5;
    float band = exp(-abs(dot(xi, normalize(vec3(0.3, 1.0, -0.2)))) * 3.5);
    col += mix(a, b, 0.5 + 0.5 * nb) * 0.03 * smoothstep(-0.2, 1.0, nb) * (0.4 + 0.6 * nb2) * band;
    vec3 sp = xi * 160.0;
    vec3 h = br_hash3(uvec3(ivec3(floor(sp)) + 4096));
    vec3 f = fract(sp) - 0.5 - (h - 0.5) * 0.6;
    col += mix(vec3(0.6, 0.75, 1.0), vec3(1.0, 0.85, 0.7), h.z) * step(0.94, h.x) * exp(-dot(f, f) * 60.0) * (0.2 + 0.8 * h.y * h.y) * (0.6 + 0.6 * band);
    float sd = max(dot(xi, sunDir), 0.0);
    col += sunCol * (0.6 * pow(sd, 900.0) + 0.05 * pow(sd, 40.0) + 0.012 * pow(sd, 6.0));
    return col;
}

vec3 hyperbolicBoids(vec2 uv, float time, sampler2D state, sampler2D proj, sampler2D tiles, sampler2D trailTex, float count, float predators, float boidSize, float glow, float trailGlow, float fog, float lattice, float music, vec3 colorA, vec3 colorB, vec3 colorC, vec3 predatorColor, vec3 latticeColor) {
    // cameras: world frame and the same frame folded into the honeycomb's base cell
    vec4 P = texelFetch(state, ivec2(514 + 3, 0), 0);
    vec4 R = texelFetch(state, ivec2(514 + 4, 0), 0);
    vec4 U = texelFetch(state, ivec2(514 + 5, 0), 0);
    vec4 F = texelFetch(state, ivec2(514 + 6, 0), 0);
    vec4 Pl = texelFetch(state, ivec2(514 + 7, 0), 0);
    vec4 Rl = texelFetch(state, ivec2(514 + 8, 0), 0);
    vec4 Ul = texelFetch(state, ivec2(514 + 9, 0), 0);
    vec4 Fl = texelFetch(state, ivec2(514 + 10, 0), 0);
    vec4 g0 = texelFetch(state, ivec2(514, 0), 0);
    if (!(P.w >= 1.0)) return vec3(0.0);
    float wl = sqrt(dot(uv, uv) + 1.7 * 1.7);
    vec4 v = (uv.x * R + uv.y * U + 1.7 * F) / wl;
    vec4 vl = (uv.x * Rl + uv.y * Ul + 1.7 * Fl) / wl;
    float pxs = 2.0 / u_resolution.y;            // pixel size in screen units
    float pixA = pxs / wl;                        // ... as an angle
    float kick = music * u_kick;                // music drive (0 when silent) x kick envelope

    vec3 sunDir = normalize(vec3(0.35, 0.8, 0.5));
    vec4 xiSun = vec4(sunDir, 1.0);
    vec3 sunCol = mix(colorC, vec3(1.0, 0.95, 0.85), 0.6);

    int n = clamp(int(count + 0.5), 0, 512);
    int np = clamp(int(predators + 0.5), 0, 2);

    // ---- cull: screen boxes from the projection pass; halos; body bounding balls
    int bIdx[6];
    float bL[6];
    float bS1[6];
    float bS2[6];
    int nb = 0;
    vec3 halo = vec3(0.0);
    // tile of this pixel (uv-space grid, same for every render target): two 24-bit masks per word,
    // bodies / halos in texels 0..5, trails in 6..11
    ivec2 tile = ivec2(clamp(floor((uv + vec2(1.6, 1.0)) / vec2(3.2, 2.0) * vec2(80.0, 50.0)), vec2(0.0), vec2(80.0 - 1.0, 50.0 - 1.0)));
    int nw = (n + 95) / 96;
    for (int t = 0; t < 6; t++) {
        if (t >= nw && !(t == 5 && np > 0)) continue;
        vec4 wv = texelFetch(tiles, ivec2(tile.x * 12 + t, tile.y), 0);
        for (int ch = 0; ch < 4; ch++) {
            uint bits = uint(wv[ch]);
            while (bits != 0u) {
                int i = (t * 4 + ch) * 24 + int(log2(float(bits & (~bits + 1u))) + 0.5);   // lowest set bit
                bits &= bits - 1u;
                vec4 bb = texelFetch(proj, ivec2(i, 10), 0);
                if (uv.x < bb.x || uv.y < bb.y || uv.x > bb.z || uv.y > bb.w) continue;
                vec4 c = texelFetch(state, ivec2(i, 0), 0);
                vec4 inf = texelFetch(proj, ivec2(i, 8), 0);
                float L = inf.w;
                float A = -br_dot(P, c);
                float B = -br_dot(v, c);
                float ts = -B / A;
                float fc = ts <= 0.0 ? A : sqrt(max(A * A - B * B, 1.0));   // cosh of the closest approach
                float sh2 = max(fc * fc - 1.0, 0.0);
                float Hr = sinh(L * 1.5);
                float hl = max(1.0 - sh2 / (Hr * Hr), 0.0);
                if (hl > 0.0) {
                    float sc = atanh(clamp(ts, 0.0, 0.999));
                    vec3 hc = inf.y > 0.5 ? predatorColor * 3.0 : br_pal(inf.x, colorA, colorB, colorC) * (1.0 + 1.5 * inf.z);
                    halo += hc * hl * hl * hl * exp(-sc * fog) * (0.15 + 0.85 * smoothstep(0.6, 2.5, sc));
                }
                float Rb = 0.72 * L;
                float C = cosh(Rb);
                float disc = C * C - (A * A - B * B);
                if (disc > 0.0) {
                    float sq = sqrt(disc);
                    float s1 = max(log(max((C - sq) / (A + B), 1e-6)), 0.0);
                    float s2 = log(max((C + sq) / (A + B), 1e-6));
                    if (s2 > 0.0) {
                        int slot = nb;
                        if (nb == 6) {
                            // full: replace the farthest candidate if this one is nearer
                            float far = -1.0;
                            for (int j = 0; j < 6; j++) if (bS1[j] > far) { far = bS1[j]; slot = j; }
                            if (s1 >= far) slot = -1;
                        } else {
                            nb++;
                        }
                        if (slot >= 0) { bIdx[slot] = i; bL[slot] = L; bS1[slot] = s1; bS2[slot] = s2; }
                    }
                }
            }
        }
    }
    // ---- sphere-trace each candidate bird inside its bounding ball, in the bird's normal coordinates
    // (log map at the boid; frame heading / up / side). The nearest hit or near miss (silhouette AA) wins.
    float sHit = -1.0;
    float cover = 0.0;
    int hi = 0;
    float hL = 1.0;
    vec4 hP4 = vec4(0.0);
    vec4 hV4 = vec4(0.0);
    vec4 hM = vec4(0.0);
    float sNear = 1e9;
    for (int j = 0; j < 6; j++) {
        if (j >= nb) break;
        if (bS1[j] > sNear) continue;
        int i = bIdx[j];
        float L = bL[j];
        vec4 c = texelFetch(state, ivec2(i, 0), 0);
        vec4 f = br_unit(texelFetch(state, ivec2(i, 1), 0));
        vec4 u = texelFetch(state, ivec2(i, 2), 0);
        vec4 sd = br_unit(br_cross4(c, f, u));
        vec4 P4 = vec4(-br_dot(P, c), br_dot(P, f), br_dot(P, u), br_dot(P, sd));
        vec4 V4 = vec4(-br_dot(v, c), br_dot(v, f), br_dot(v, u), br_dot(v, sd));
        vec4 m = texelFetch(state, ivec2(i, 3), 0);
        bool pr = i >= 512;
        vec4 bm = vec4(m.x, mix(0.12, 0.85, m.y) * (pr ? 0.7 : 1.0), pr ? 1.35 : 1.0, 0.0);
        float s = bS1[j];
        float best = 1e9;
        float sb = s;
        for (int it = 0; it < 40; it++) {
            float e = exp(s);
            vec4 Lc = (0.5 * (e + 1.0 / e)) * P4 + (0.5 * (e - 1.0 / e)) * V4;
            float r = length(Lc.yzw);
            vec3 X = Lc.yzw * (r > 1e-6 ? br_asinh(r) / r : 1.0) / L;
            float pt;
            float d = br_bird(X, bm.x, bm.y, bm.z, pt) * L;
            float fp = sinh(max(s, 1e-3)) * pixA;          // pixel footprint at this distance
            float ratio = d / fp;
            if (ratio < best) { best = ratio; sb = s; }
            if (ratio < 0.3) break;
            s += max(d * 0.9, 0.2 * fp);
            if (s > bS2[j]) break;
        }
        // a full hit always beats a near miss (near misses only anti-alias against the background)
        float cv = best < 0.3 ? 1.0 : 1.0 - smoothstep(0.3, 1.2, best);
        if (best < 1.2 && (cv > cover || (cv == cover && sb < sNear))) {
            sNear = cv == 1.0 ? sb : 1e9;
            sHit = sb;
            cover = cv;
            hi = i;
            hL = L;
            hP4 = P4;
            hV4 = V4;
            hM = bm;
        }
    }

    vec3 col;
    vec3 body = vec3(0.0);
    if (sHit >= 0.0) {
        float e = exp(sHit);
        float ch = 0.5 * (e + 1.0 / e);
        float sh = 0.5 * (e - 1.0 / e);
        vec4 q = ch * P + sh * v;
        vec4 V = sh * P + ch * v;
        int i = hi;
        float L = hL;
        vec4 c = texelFetch(state, ivec2(i, 0), 0);
        vec4 f = br_unit(texelFetch(state, ivec2(i, 1), 0));
        vec4 u = texelFetch(state, ivec2(i, 2), 0);
        vec4 sd = br_unit(br_cross4(c, f, u));
        vec4 Lc = ch * hP4 + sh * hV4;
        float r = length(Lc.yzw);
        vec3 X = Lc.yzw * (r > 1e-6 ? br_asinh(r) / r : 1.0) / L;
        vec4 bm = hM;
        float part;
        br_bird(X, bm.x, bm.y, bm.z, part);
        // normal: tetrahedral gradient in the bird frame, mapped to the tangent space at the hit
        const vec2 kk = vec2(1.0, -1.0);
        float hh = 0.004;
        float pd;
        vec3 g = kk.xyy * br_bird(X + kk.xyy * hh, bm.x, bm.y, bm.z, pd)
               + kk.yyx * br_bird(X + kk.yyx * hh, bm.x, bm.y, bm.z, pd)
               + kk.yxy * br_bird(X + kk.yxy * hh, bm.x, bm.y, bm.z, pd)
               + kk.xxx * br_bird(X + kk.xxx * hh, bm.x, bm.y, bm.z, pd);
        vec4 N = br_unit(br_tan(g.x * f + g.y * u + g.z * sd, q));
        float NdV = clamp(-br_dot(N, V), 0.0, 1.0);
        vec4 Ls = br_unit(br_tan(xiSun, q));            // towards the ideal light point
        float dif = max(br_dot(N, Ls), 0.0);
        vec4 Hh = br_unit(Ls - V);
        float spec = pow(max(br_dot(N, Hh), 0.0), 60.0);
        vec4 Rf = V - 2.0 * br_dot(V, N) * N;
        vec3 env = br_sky(q, Rf, colorA, colorB, sunDir, sunCol);
        float fres = 0.04 + 0.96 * pow(1.0 - NdV, 5.0);
        vec4 inf = texelFetch(proj, ivec2(i, 8), 0);
        if (inf.y > 0.5) {
            // predator: dark lacquer with an ember rim and burning eyes
            float eye = smoothstep(0.03, 0.0, length(vec2(X.x - 0.37, abs(X.z) - 0.035)) - 0.012 + abs(X.y - 0.05) * 0.5);
            body = predatorColor * (0.04 + 0.2 * dif) + predatorColor * pow(1.0 - NdV, 2.0) * 3.0 * glow;
            body += predatorColor * (part == 1.0 ? smoothstep(0.25, 0.6, abs(X.z)) : 0.25) * 1.2 * glow;
            body += env * (0.15 + 1.2 * fres) + vec3(1.0, 0.9, 0.8) * spec * 0.6;
            body += mix(predatorColor, vec3(1.0, 0.9, 0.5), 0.5) * eye * 6.0 * glow * (1.0 + kick);
        } else {
            // boid: thin-film iridescence (hue shifts with the viewing angle), emissive spine
            float hue = inf.x;
            float panic = inf.z;
            vec3 film = br_pal(hue + 0.55 * (1.0 - NdV) + 0.07 * part + 0.1 * X.x, colorA, colorB, colorC);
            vec3 base = br_pal(hue, colorA, colorB, colorC);
            float spine = part == 1.0 ? smoothstep(0.2, 0.55, abs(X.z)) * 0.6 : (part == 2.0 ? 0.5 : 1.0);
            float fill = max(-br_dot(N, Ls), 0.0);            // cool fill from the antipodal side
            body = film * (0.08 + 0.45 * dif) + colorA * film * fill * 0.18 + film * pow(1.0 - NdV, 2.0) * 0.9;
            body += env * (0.05 + 0.6 * fres) + vec3(1.0, 0.97, 0.9) * spec * 0.6;
            body += base * spine * (0.25 + 0.9 * panic) * glow * (1.0 + 0.8 * kick);
        }
        body *= cover;
    }

    // ---- honeycomb walk: Klein cube cells, rays reflected into the neighbour cell at each face
    const float A = 0.48586827;
    float Dstop = sHit >= 0.0 && cover > 0.6 ? sHit : 9.0;
    vec4 hp = Pl;
    vec4 hv = vl;
    float D = 0.0;
    vec3 wire = vec3(0.0);
    if (lattice > 0.0) {
        for (int it = 0; it < 18; it++) {
            float tExit = 0.99999;
            int ef = 0;
            for (int k = 0; k < 6; k++) {
                vec4 fn = br_face(k);
                float vn = br_dot(hv, fn);
                if (vn > 1e-7) {
                    float t = max(-br_dot(hp, fn) / vn, 0.0);
                    if (t < tExit) { tExit = t; ef = k; }
                }
            }
            float seg = atanh(tExit);
            if (D + seg > Dstop) break;
            float chx = inversesqrt(max(1.0 - tExit * tExit, 1e-9));
            vec4 pn = (hp + tExit * hv) * chx;
            vec4 vn = (tExit * hp + hv) * chx;
            D += seg;
            vec3 ak = abs(pn.xyz / pn.w);
            int ej = ef / 2;
            vec2 o = ej == 0 ? ak.yz : (ej == 1 ? ak.xz : ak.xy);
            float m1 = max(o.x, o.y);
            float m2 = min(o.x, o.y);
            // wire width ~ constant hyperbolic width on the face; fade to coverage when sub-pixel
            float fpk = pixA * sinh(D) * 0.75;
            float band = max(0.003, fpk);
            float wv = smoothstep(A - band * 1.6, A - band * 0.3, m1) * (0.003 / band);
            float vx = smoothstep(A - band * 5.0, A - band * 0.5, m2) * smoothstep(A - band * 3.0, A, m1) * min(1.0, 0.008 / band);
            float fw = exp(-D * (fog * 1.5 + 0.3));
            if (fw < 0.015) break;
            wire += latticeColor * (wv * 0.22 + vx * 0.7 * (1.0 + kick)) * fw * smoothstep(0.05, 0.4, D);
            vec4 fn = br_face(ef);
            hp = br_toH(pn - 2.0 * br_dot(pn, fn) * fn);
            hv = br_unit(br_tan(vn - 2.0 * br_dot(vn, fn) * fn, hp));
        }
    }
    wire *= lattice;

    vec3 fogCol = vec3(0.006, 0.009, 0.022) + mix(colorA, colorB, 0.4) * 0.012;
    if (sHit >= 0.0) {
        float T = exp(-sHit * fog);
        vec3 bg = br_sky(P, v, colorA, colorB, sunDir, sunCol) * exp(-9.0 * fog) + fogCol * (1.0 - exp(-9.0 * fog));
        col = mix(bg, body * T + fogCol * (1.0 - T), cover) + wire;
    } else {
        float T = exp(-9.0 * fog);
        col = br_sky(P, v, colorA, colorB, sunDir, sunCol) * (0.25 + 0.75 * T) + fogCol * (1.0 - T) + wire;
    }

    // ---- trails: drawn at half resolution by the Boid Trails pass; rgb = light, a = depth of the trail
    vec4 tr = texture(trailTex, gl_FragCoord.xy / u_resolution);
    vec3 trails = tr.rgb * ((sHit >= 0.0 && tr.a > sHit + 0.03) ? 1.0 - 0.9 * cover : 1.0);
    col += trails * trailGlow * 0.55 * (1.0 + 0.5 * kick);
    col += halo * glow * 0.035 * (1.0 + kick);
    return col;
}

BoidStreak.customGLSL:
// @node boidStreak
// @title Anamorphic Streak
// @category effect
// @description Wide horizontal lens streak of a bright-pass texture (blur along x only, width in UV units) at the current pixel.
vec3 boidStreak(sampler2D tex, float width) {
    vec2 uv = gl_FragCoord.xy / u_resolution;
    vec3 acc = vec3(0.0);
    float wsum = 0.0;
    for (int i = -16; i <= 16; i++) {
        float x = float(i) / 16.0;
        float wt = exp(-x * x * 4.0);
        acc += texture(tex, uv + vec2(x * width, 0.0)).rgb * wt;
        wsum += wt;
    }
    return acc / wsum;
}

BoidSim.customGLSL:
    // @node boidSim
// @title Hyperbolic Boids Sim
// @category custom
// @description Boid flocking in H3 for an 526x16 rgba32f / nearest Feedback (wire its out back into state). Columns 0..511 are boids, 512..513 predators, 514.. globals. Rows: 0 position p on the hyperboloid <p,p> = -1 | 1 velocity v (tangent, <p,v> = 0) | 2 up vector (banking) | 3 (wing phase, flap effort, panic, hue) | 4..15 trail history. Steering is intrinsic: neighbour distance acosh(-<p,q>), directions from the log map, neighbour velocities parallel-transported to p before averaging; geodesic steps with the exponential map. Globals: clock (shift phase, time, simT, tick), smoothed flock centre, orbit state, camera frame (world and folded into the {4,3,5} base cell), wandering attractor.
// ---- H3 helpers, hyperboloid model: <a,b> = a.x b.x + a.y b.y + a.z b.z - a.w b.w, <p,p> = -1 ----
float bs_dot(vec4 a, vec4 b) {
    return dot(a.xyz, b.xyz) - a.w * b.w;
}

// Back onto the upper sheet of the hyperboloid
vec4 bs_toH(vec4 p) {
    return p / sqrt(max(-bs_dot(p, p), 1e-12));
}

// Tangent projection at p
vec4 bs_tan(vec4 v, vec4 p) {
    return v + bs_dot(v, p) * p;
}

vec4 bs_unit(vec4 v) {
    return v * inversesqrt(max(bs_dot(v, v), 1e-14));
}

float bs_acosh(float c) {
    c = max(c, 1.0);
    return log(c + sqrt(c * c - 1.0));
}

float bs_asinh(float x) {
    return log(x + sqrt(x * x + 1.0));
}

// Log map: tangent vector at p pointing to q, length = d(p, q)
vec4 bs_log(vec4 p, vec4 q) {
    float c = max(-bs_dot(p, q), 1.0);
    float sh = sqrt(c * c - 1.0);
    if (sh < 1e-7) return vec4(0.0);
    return (q - c * p) * (log(c + sh) / sh);
}

// Exponential map: walk the geodesic from p with initial velocity v for |v|
vec4 bs_exp(vec4 p, vec4 v) {
    float n = sqrt(max(bs_dot(v, v), 0.0));
    if (n < 1e-8) return p;
    return cosh(n) * p + (sinh(n) / n) * v;
}

// Parallel transport of w (tangent at q) along the geodesic q -> p
vec4 bs_transport(vec4 w, vec4 q, vec4 p) {
    return w + bs_dot(p, w) / (1.0 - bs_dot(q, p)) * (q + p);
}

// Lorentz-orthogonal complement of three vectors (generalized cross product, index lowered)
vec4 bs_cross4(vec4 a, vec4 b, vec4 c) {
    float x = dot(a.yzw, cross(b.yzw, c.yzw));
    float y = -dot(a.xzw, cross(b.xzw, c.xzw));
    float z = dot(a.xyw, cross(b.xyw, c.xyw));
    float w = -dot(a.xyz, cross(b.xyz, c.xyz));
    return vec4(x, y, z, -w);
}

vec3 bs_hash3(uvec3 v) {
    v = v * 1664525u + 1013904223u;
    v.x += v.y * v.z; v.y += v.z * v.x; v.z += v.x * v.y;
    v ^= v >> 16u;
    v.x += v.y * v.z; v.y += v.z * v.x; v.z += v.x * v.y;
    return vec3(v) * (1.0 / 4294967296.0);
}

// Outward unit normal of face k of the {4,3,5} base cell (Klein cube |x_j| <= A)
vec4 bs_face(int k) {
    const float A = 0.48586827;
    int j = k / 2;
    float s = (k - j * 2 == 0) ? 1.0 : -1.0;
    vec3 e = j == 0 ? vec3(1.0, 0.0, 0.0) : (j == 1 ? vec3(0.0, 1.0, 0.0) : vec3(0.0, 0.0, 1.0));
    return vec4(e * s, A) * 1.1441228;   // 1 / sqrt(1 - A^2)
}

// Three-colour cyclic palette
vec3 bs_pal(float t, vec3 a, vec3 b, vec3 c) {
    t = fract(t) * 3.0;
    if (t < 1.0) return mix(a, b, smoothstep(0.0, 1.0, t));
    if (t < 2.0) return mix(b, c, smoothstep(1.0, 2.0, t));
    return mix(c, a, smoothstep(2.0, 3.0, t));
}


// Deterministic seed: boids in a ball of radius ~0.9, predators farther out
void bs_seed(int i, float sig0, out vec4 p, out vec4 v, out vec4 u, out vec4 m) {
    vec3 h = bs_hash3(uvec3(uint(i), 11u, 5u));
    vec3 h2 = bs_hash3(uvec3(uint(i), 23u, 9u));
    bool pred = i >= 512;
    float r = pred ? 1.6 : 0.95 * pow(h.x, 0.333);
    float z = 2.0 * h.y - 1.0;
    float a = 6.2831853 * h.z;
    vec3 dir = vec3(sqrt(max(1.0 - z * z, 0.0)) * vec2(cos(a), sin(a)), z).xzy;
    p = vec4(sinh(r) * dir, cosh(r));
    // random heading, biased a little towards +x so the flock forms in a few seconds
    float z2 = 2.0 * h2.x - 1.0;
    float a2 = 6.2831853 * h2.y;
    vec3 hd = normalize(vec3(sqrt(max(1.0 - z2 * z2, 0.0)) * vec2(cos(a2), sin(a2)), z2) + vec3(0.6, 0.0, 0.2));
    vec4 o = vec4(0.0, 0.0, 0.0, 1.0);
    vec4 f = bs_unit(bs_tan(bs_transport(vec4(hd, 0.0), o, p), p));
    v = f * sig0;
    vec4 up = bs_tan(bs_transport(vec4(0.0, 1.0, 0.0, 0.0), o, p), p);
    up = bs_unit(up - bs_dot(up, f) * f);
    u = up;
    m = vec4(6.2831853 * h2.z, 0.5, pred ? 13.0 * float(i - 512) : 0.0, fract(h.x * 7.31 + h.y * 3.17 + float(i) * 0.618034));
}

bool bs_valid(vec4 p, vec4 v) {
    float c = bs_dot(p, p) + 1.0;
    float s = bs_dot(v, v);
    return p.w >= 1.0 && p.w < 1e4 && abs(c) < 0.05 && s > 1e-10 && s < 100.0;
}

// Attractor: a slowly wandering point within ~0.8 of the origin (soft containment pulls towards it)
vec4 bs_attractor(float t) {
    float r = 0.45 + 0.25 * sin(t * 0.041);
    float th = t * 0.063 + 0.9 * sin(t * 0.023);
    float ph = 0.45 * sin(t * 0.051 + 1.3);
    vec3 d = vec3(cos(ph) * cos(th), sin(ph), cos(ph) * sin(th));
    return vec4(sinh(r) * d, cosh(r));
}

// Orbit camera around the smoothed flock centre c at distance D, azimuth th, elevation ph
void bs_orbitCam(vec4 c, float th, float ph, float D, out vec4 P, out vec4 R, out vec4 U, out vec4 F) {
    // world axes transported from the origin to c
    float k = 1.0 / (1.0 + c.w);
    vec4 oc = vec4(c.xyz, c.w + 1.0);
    vec4 Ex = vec4(1.0, 0.0, 0.0, 0.0) + c.x * k * oc;
    vec4 Ey = vec4(0.0, 1.0, 0.0, 0.0) + c.y * k * oc;
    vec4 Ez = vec4(0.0, 0.0, 1.0, 0.0) + c.z * k * oc;
    vec4 hor = cos(th) * Ex + sin(th) * Ez;
    vec4 dir = cos(ph) * hor + sin(ph) * Ey;
    P = cosh(D) * c + sinh(D) * dir;
    F = -(sinh(D) * c + cosh(D) * dir);     // back along the geodesic, towards c
    U = -sin(ph) * hor + cos(ph) * Ey;        // orthogonal to the plane (c, dir): unchanged by transport
    R = sin(th) * Ex - cos(th) * Ez;
    // tidy up (fp32)
    P = bs_toH(P);
    F = bs_unit(bs_tan(F, P));
    U = bs_tan(U, P); U = bs_unit(U - bs_dot(U, F) * F);
    R = bs_tan(R, P); R = bs_unit(R - bs_dot(R, F) * F - bs_dot(R, U) * U);
}

vec4 bs_globals(int idx, sampler2D state, float time, float dt, float dH, float simT, float tick, bool init, int n, float camSpeed, float camDistance) {
    if (idx == 0) return vec4(fract(simT / dH), time, simT, tick);
    if (idx == 11) return bs_attractor(time);
    // flock centre (Lorentzian centroid) and spread: mean cosh(d) = |sum p|_L / n
    vec4 S = vec4(0.0);
    for (int j = 0; j < 512; j++) {
        if (j >= n) break;
        S += texelFetch(state, ivec2(j, 0), 0);
    }
    float nl = sqrt(max(-bs_dot(S, S), 1e-12));
    vec4 ct = n > 0 ? S / nl : vec4(0.0, 0.0, 0.0, 1.0);
    float spread = n > 0 ? bs_acosh(nl / float(n)) : 0.5;
    vec4 cPrev = texelFetch(state, ivec2(514 + 1, 0), 0);
    vec4 g2 = texelFetch(state, ivec2(514 + 2, 0), 0);
    bool ok = !init && cPrev.w >= 1.0 && cPrev.w < 1e3 && g2.y > 0.0 && g2.y < 10.0;
    vec4 c = ok ? bs_toH(bs_exp(cPrev, bs_log(cPrev, ct) * (1.0 - exp(-dt / 1.1)))) : ct;
    float th = ok ? mod(g2.x + camSpeed * dt, 6.2831853) : 2.4;
    float sp = ok ? mix(g2.z, spread, 1.0 - exp(-dt / 2.0)) : spread;
    float Dt = clamp(camDistance * bs_asinh(2.8 * sinh(1.15 * sp + 0.2)), 0.45, 3.5);
    Dt *= 0.78 + 0.3 * (0.5 + 0.5 * sin(time * 0.043 + 1.1));     // slow push-in / pull-out
    float D = ok ? mix(g2.y, Dt, 1.0 - exp(-dt / 2.5)) : Dt;
    if (idx == 1) return c;
    if (idx == 2) return vec4(th, D, sp, 1.0);
    float ph = 0.3 + 0.24 * sin(time * 0.037 + 0.6);
    vec4 P, R, U, F;
    bs_orbitCam(c, th, ph, D, P, R, U, F);
    if (idx < 7) return idx == 3 ? P : (idx == 4 ? R : (idx == 5 ? U : F));
    // fold the camera into the base cell of the {4,3,5} honeycomb (Lorentz reflections in its faces)
    for (int it = 0; it < 32; it++) {
        bool moved = false;
        for (int k = 0; k < 6; k++) {
            vec4 fn = bs_face(k);
            float d = bs_dot(P, fn);
            if (d > 1e-6) {
                P -= 2.0 * d * fn;
                R -= 2.0 * bs_dot(R, fn) * fn;
                U -= 2.0 * bs_dot(U, fn) * fn;
                F -= 2.0 * bs_dot(F, fn) * fn;
                moved = true;
            }
        }
        if (!moved) break;
    }
    P = bs_toH(P);
    if (idx == 7) return P;
    if (idx == 8) return bs_tan(R, P);
    if (idx == 9) return bs_tan(U, P);
    return bs_tan(F, P);
}

vec4 boidSim(sampler2D state, float time, float count, float separation, float alignment, float cohesion, float perception, float spacing, float speed, float containment, float predators, float camSpeed, float camDistance, float trailLength) {
    ivec2 px = ivec2(gl_FragCoord.xy);
    int i = px.x;
    int row = px.y;
    vec4 g0 = texelFetch(state, ivec2(514, 0), 0);
    vec4 g2 = texelFetch(state, ivec2(514 + 2, 0), 0);
    // zeroed buffer, clock moved backwards or broken globals: reseed everything
    bool init = g2.w != 1.0 || !(g0.y > 0.0) || time < g0.y - 1.0 || !(g0.z >= 0.0 && g0.z < 1e6);
    float dt = init ? 0.0 : clamp(time - g0.y, 0.0, 0.1);
    float dH = max(trailLength, 0.1) / 12.0;
    float simT = init ? 0.0 : mod(g0.z + dt, dH * 1000.0);
    float tick = floor(simT / dH);
    bool shift = init || tick != g0.w;
    int n = clamp(int(count + 0.5), 0, 512);
    int np = clamp(int(predators + 0.5), 0, 2);
    float sig0 = max(speed, 0.02);

    if (i >= 514) {
        if (row != 0) return vec4(0.0);
        return bs_globals(i - 514, state, time, dt, dH, simT, tick, init, n, camSpeed, camDistance);
    }

    vec4 p = texelFetch(state, ivec2(i, 0), 0);
    vec4 v = texelFetch(state, ivec2(i, 1), 0);
    bool bad = init || !bs_valid(p, v);
    vec4 sp0, sv0, su0, sm0;
    if (bad) bs_seed(i, sig0, sp0, sv0, su0, sm0);

    // trail history: a shift register of past positions, one step every trailLength / K seconds
    if (row >= 4) {
        if (bad) return sp0;
        if (!shift) return texelFetch(state, px, 0);
        return row == 4 ? p : texelFetch(state, ivec2(i, row - 1), 0);
    }
    if (bad) return row == 0 ? sp0 : (row == 1 ? sv0 : (row == 2 ? su0 : sm0));

    vec4 u = texelFetch(state, ivec2(i, 2), 0);
    vec4 m = texelFetch(state, ivec2(i, 3), 0);
    bool pred = i >= 512;
    bool alive = pred ? (i - 512) < np : i < n;
    vec3 hi = bs_hash3(uvec3(uint(i), 41u, 3u));

    float spd = sqrt(max(bs_dot(v, v), 1e-12));
    vec4 f = v / spd;
    vec4 acc = vec4(0.0);
    float threat = 0.0;
    float amax = sig0 * 3.0;
    float sigT = sig0 * (0.9 + 0.2 * hi.x);

    // soft containment towards the wandering attractor
    vec4 at = texelFetch(state, ivec2(514 + 11, 0), 0);
    if (!(at.w >= 1.0 && at.w < 100.0)) at = vec4(0.0, 0.0, 0.0, 1.0);
    vec4 la = bs_log(p, at);
    float da = sqrt(max(bs_dot(la, la), 0.0));
    vec4 ea = la / max(da, 1e-5);
    float R0 = pred ? 1.5 : 0.95;

    if (!pred) {
        if (alive) {
            float R = max(perception, 0.02);
            float Rs = max(spacing, 0.005);
            float chR = cosh(max(R, Rs));
            vec4 sep = vec4(0.0);
            vec4 coh = vec4(0.0);
            vec4 ali = vec4(0.0);
            float wsum = 0.0;
            for (int j = 0; j < 512; j++) {
                if (j >= n) break;
                if (j == i) continue;
                vec4 q = texelFetch(state, ivec2(j, 0), 0);
                float c = -bs_dot(p, q);
                if (!(c < chR)) continue;
                c = max(c, 1.0 + 1e-6);
                float sh = sqrt(c * c - 1.0);
                float d = log(c + sh);
                vec4 e = (q - c * p) / sh;                  // log map direction
                if (d < Rs) {
                    float x = d / Rs;
                    sep -= e * (1.0 - x) * (1.0 - x) / max(x, 0.2);
                }
                float w = max(1.0 - d / R, 0.0);
                w *= w * smoothstep(-0.8, -0.4, bs_dot(e, f));   // blind spot behind
                if (w > 0.0) {
                    vec4 vj = texelFetch(state, ivec2(j, 1), 0);
                    ali += w * bs_transport(vj, q, p);        // neighbour velocity, transported to p
                    coh += w * d * e;                          // log map of the neighbour
                    wsum += w;
                }
            }
            if (wsum > 1e-4) {
                acc += alignment * 1.5 * (ali / wsum - v);
                acc += cohesion * 1.0 * (coh / wsum);
            }
            acc += separation * sig0 * 4.0 * sep;
            // flee from predators
            float Rp = max(2.0 * R, 0.5);
            for (int k = 0; k < 2; k++) {
                if (k >= np) break;
                vec4 q = texelFetch(state, ivec2(512 + k, 0), 0);
                vec4 l = bs_log(p, q);
                float d = sqrt(max(bs_dot(l, l), 1e-10));
                if (d < Rp) {
                    float t = 1.0 - d / Rp;
                    acc -= (l / d) * t * t * sig0 * 7.0;
                    threat = max(threat, t);
                }
            }
        }
        acc += containment * sig0 * ea * min(0.35 * da + 2.0 * max(da - R0, 0.0), 6.0);
        sigT *= 1.0 + 0.8 * threat;
        amax *= 1.0 + threat;
    } else {
        // predators: hunt the nearest boid for 15 s, then cruise for 11 s
        float cyc = mod(m.z + dt, 26.0);
        float hunt = alive ? smoothstep(0.0, 1.0, cyc) * (1.0 - smoothstep(14.0, 15.0, cyc)) : 0.0;
        float best = 1e9;
        vec4 tgt = at;
        if (hunt > 0.0) {
            for (int j = 0; j < 512; j++) {
                if (j >= n) break;
                vec4 q = texelFetch(state, ivec2(j, 0), 0);
                float c = -bs_dot(p, q) - 0.15 * bs_dot(f, q);   // prefer prey ahead
                if (c < best) { best = c; tgt = q; }
            }
        }
        vec4 lt = bs_log(p, tgt);
        float dtg = sqrt(max(bs_dot(lt, lt), 1e-10));
        vec4 desired = (lt / dtg) * sig0 * 1.55;
        acc += hunt * 1.3 * (desired - v);
        // cruising: lurk about 1.1 from the flock centre, drifting
        vec3 hw = bs_hash3(uvec3(uint(i), uint(floor(time * 0.2)), 77u)) - 0.5;
        acc += (1.0 - hunt) * sig0 * 0.6 * bs_tan(vec4(hw, 0.0), p);
        vec4 fc = texelFetch(state, ivec2(514 + 1, 0), 0);
        if (fc.w >= 1.0 && fc.w < 1e3) {
            vec4 lc = bs_log(p, fc);
            float dc = sqrt(max(bs_dot(lc, lc), 1e-10));
            acc += (1.0 - hunt) * sig0 * 1.2 * (lc / dc) * clamp(dc - 1.1, -1.0, 1.5);
        }
        acc += containment * sig0 * ea * min(0.2 * da + 1.5 * max(da - R0, 0.0), 4.0);
        for (int k = 0; k < 2; k++) {
            int o = 512 + k;
            if (o == i || k >= np) continue;
            vec4 l = bs_log(p, texelFetch(state, ivec2(o, 0), 0));
            float d = sqrt(max(bs_dot(l, l), 1e-10));
            if (d < 0.6) acc -= (l / d) * (1.0 - d / 0.6) * sig0 * 3.0;
        }
        sigT = sig0 * mix(0.75, 1.55, hunt);
        amax = sig0 * 1.7;
        m.z = cyc;
    }

    // individual wander (keeps the flock from freezing into a crystal)
    vec4 side = bs_unit(bs_cross4(p, f, u));
    float wt = time * (0.5 + 0.4 * hi.y) + 6.2831853 * hi.z;
    acc += sig0 * 0.35 * (sin(wt) * u + cos(wt * 0.73 + 1.7) * side);
    // bounded steering, tangent at p, then cruise-speed control (bounded on its own, so a strong
    // pull can never starve the brakes)
    acc = bs_tan(acc, p);
    float an = sqrt(max(bs_dot(acc, acc), 0.0));
    if (an > amax) acc *= amax / an;
    acc += f * clamp((sigT - spd) * 2.0, -amax, amax);
    if (!alive) acc = bs_tan(ea * da * sig0 * 0.5 + f * (sig0 - spd), p);

    v = bs_tan(v + acc * dt, p);
    spd = clamp(sqrt(max(bs_dot(v, v), 1e-12)), 0.35 * sig0, (pred ? 1.8 : 2.4) * sig0);
    f = bs_unit(v);

    // banking: up vector leans into the turn (lateral acceleration), relaxes to "world up"
    vec4 Y = bs_tan(vec4(0.0, 1.0, 0.0, 0.0), p);
    Y -= bs_dot(Y, f) * f;
    float yl = bs_dot(Y, Y);
    u = bs_tan(u, p);
    u -= bs_dot(u, f) * f;
    u = bs_unit(u);
    vec4 aLat = acc - bs_dot(acc, f) * f;
    vec4 ut = (yl > 1e-6 ? Y * inversesqrt(yl) : u) + aLat * (0.8 / sig0);
    ut -= bs_dot(ut, f) * f;
    u = bs_unit(mix(u, bs_unit(ut), 1.0 - exp(-dt * 3.0)));

    // wings: flap harder when accelerating, climbing or fleeing; glide now and then
    float climb = bs_dot(f, Y) * inversesqrt(max(yl, 1e-6) + 1.0);
    float effort = clamp(0.25 + 0.7 * an / amax + 1.5 * climb + threat, 0.0, 1.0);
    float glide = smoothstep(0.55, 0.9, sin(time * (0.21 + 0.1 * hi.y) + 6.2831853 * hi.x)) * (1.0 - threat);
    effort *= 1.0 - 0.85 * glide;
    m.y = mix(m.y, effort, 1.0 - exp(-dt * 2.5));
    m.x = mod(m.x + dt * (pred ? 0.6 : 1.0) * (8.0 + 10.0 * m.y), 6.2831853);
    if (!pred) m.z = max(threat, m.z * exp(-dt * 1.2));

    // geodesic step: p' = cosh(s) p + sinh(s) f, velocity transported along it (the up vector is
    // orthogonal to the geodesic plane, so transport leaves it unchanged)
    float s = spd * dt;
    vec4 p2 = bs_toH(cosh(s) * p + sinh(s) * f);
    vec4 f2 = bs_unit(bs_tan(sinh(s) * p + cosh(s) * f, p2));
    u = bs_tan(u, p2);
    u = bs_unit(u - bs_dot(u, f2) * f2);

    if (row == 0) return p2;
    if (row == 1) return f2 * spd;
    if (row == 2) return u;
    return m;
}

BoidProject.customGLSL:
// @node boidProject
// @title Boid Trail Projection
// @category custom
// @description Per-frame screen projection for the trails, into a 514x11 rgba32f / nearest Feedback (read by the scene, written after the sim). The camera frame comes from the sim state. Geodesics are straight lines in the Klein model centred on the camera, so they project to straight screen segments: each trail (the boid's tail plus its position history) is a screen polyline. Rows 0..6: two screen points per texel (x0, y0, x1, y1; 1e4 = behind the camera) | 7: screen bounding box of trail + body + halo | 8: (hue, predator, panic, body length) | 9: (trail half width, depth) at the tail | 10: screen bounding box of body + halo.
// ---- H3 helpers, hyperboloid model: <a,b> = a.x b.x + a.y b.y + a.z b.z - a.w b.w, <p,p> = -1 ----
float bp_dot(vec4 a, vec4 b) {
    return dot(a.xyz, b.xyz) - a.w * b.w;
}

// Back onto the upper sheet of the hyperboloid
vec4 bp_toH(vec4 p) {
    return p / sqrt(max(-bp_dot(p, p), 1e-12));
}

// Tangent projection at p
vec4 bp_tan(vec4 v, vec4 p) {
    return v + bp_dot(v, p) * p;
}

vec4 bp_unit(vec4 v) {
    return v * inversesqrt(max(bp_dot(v, v), 1e-14));
}

float bp_acosh(float c) {
    c = max(c, 1.0);
    return log(c + sqrt(c * c - 1.0));
}

float bp_asinh(float x) {
    return log(x + sqrt(x * x + 1.0));
}

// Log map: tangent vector at p pointing to q, length = d(p, q)
vec4 bp_log(vec4 p, vec4 q) {
    float c = max(-bp_dot(p, q), 1.0);
    float sh = sqrt(c * c - 1.0);
    if (sh < 1e-7) return vec4(0.0);
    return (q - c * p) * (log(c + sh) / sh);
}

// Exponential map: walk the geodesic from p with initial velocity v for |v|
vec4 bp_exp(vec4 p, vec4 v) {
    float n = sqrt(max(bp_dot(v, v), 0.0));
    if (n < 1e-8) return p;
    return cosh(n) * p + (sinh(n) / n) * v;
}

// Parallel transport of w (tangent at q) along the geodesic q -> p
vec4 bp_transport(vec4 w, vec4 q, vec4 p) {
    return w + bp_dot(p, w) / (1.0 - bp_dot(q, p)) * (q + p);
}

// Lorentz-orthogonal complement of three vectors (generalized cross product, index lowered)
vec4 bp_cross4(vec4 a, vec4 b, vec4 c) {
    float x = dot(a.yzw, cross(b.yzw, c.yzw));
    float y = -dot(a.xzw, cross(b.xzw, c.xzw));
    float z = dot(a.xyw, cross(b.xyw, c.xyw));
    float w = -dot(a.xyz, cross(b.xyz, c.xyz));
    return vec4(x, y, z, -w);
}

vec3 bp_hash3(uvec3 v) {
    v = v * 1664525u + 1013904223u;
    v.x += v.y * v.z; v.y += v.z * v.x; v.z += v.x * v.y;
    v ^= v >> 16u;
    v.x += v.y * v.z; v.y += v.z * v.x; v.z += v.x * v.y;
    return vec3(v) * (1.0 / 4294967296.0);
}

// Outward unit normal of face k of the {4,3,5} base cell (Klein cube |x_j| <= A)
vec4 bp_face(int k) {
    const float A = 0.48586827;
    int j = k / 2;
    float s = (k - j * 2 == 0) ? 1.0 : -1.0;
    vec3 e = j == 0 ? vec3(1.0, 0.0, 0.0) : (j == 1 ? vec3(0.0, 1.0, 0.0) : vec3(0.0, 0.0, 1.0));
    return vec4(e * s, A) * 1.1441228;   // 1 / sqrt(1 - A^2)
}

// Three-colour cyclic palette
vec3 bp_pal(float t, vec3 a, vec3 b, vec3 c) {
    t = fract(t) * 3.0;
    if (t < 1.0) return mix(a, b, smoothstep(0.0, 1.0, t));
    if (t < 2.0) return mix(b, c, smoothstep(1.0, 2.0, t));
    return mix(c, a, smoothstep(2.0, 3.0, t));
}


void bp_camera(sampler2D state, out vec4 P, out vec4 R, out vec4 U, out vec4 F) {
    P = texelFetch(state, ivec2(514 + 3, 0), 0);
    R = texelFetch(state, ivec2(514 + 4, 0), 0);
    U = texelFetch(state, ivec2(514 + 5, 0), 0);
    F = texelFetch(state, ivec2(514 + 6, 0), 0);
}

// (screen x, screen y, half width, depth) of world point x; half width = 0 when not drawable
vec4 bp_project(vec4 x, vec4 P, vec4 R, vec4 U, vec4 F, float w) {
    vec4 X = vec4(bp_dot(x, R), bp_dot(x, U), bp_dot(x, F), max(-bp_dot(x, P), 1.0));
    float sh = sqrt(max(X.w * X.w - 1.0, 1e-10));
    float d = log(X.w + sh);
    if (X.z < 0.12 * sh || d < 0.02) return vec4(0.0, 0.0, 0.0, d);
    return vec4(1.7 * X.xy / X.z, min(1.7 * sinh(w) / X.z, 0.016), d);   // near the camera: thin streamers
}

vec4 bp_point(sampler2D state, int i, int k, float L) {
    if (k == 0) {
        // tail tip: half a body length behind the centre, along the heading
        vec4 p = texelFetch(state, ivec2(i, 0), 0);
        vec4 f = bp_unit(texelFetch(state, ivec2(i, 1), 0));
        return cosh(0.45 * L) * p - sinh(0.45 * L) * f;
    }
    return texelFetch(state, ivec2(i, 3 + k), 0);
}

vec4 boidProject(sampler2D state, float count, float predators, float boidSize, float trailWidth) {
    ivec2 px = ivec2(gl_FragCoord.xy);
    int i = px.x;
    int row = px.y;
    int n = clamp(int(count + 0.5), 0, 512);
    int np = clamp(int(predators + 0.5), 0, 2);
    bool pred = i >= 512;
    bool alive = pred ? (i - 512) < np : i < n;
    if (!alive || i >= 514) return row == 7 || row == 10 ? vec4(1e4, 1e4, -1e4, -1e4) : vec4(0.0);
    float L = boidSize * (pred ? 2.4 : 1.0);
    vec4 P, R, U, F;
    bp_camera(state, P, R, U, F);
    float w = 0.5 * trailWidth * L;
    if (row < 7) {
        vec4 a = bp_project(bp_point(state, i, 2 * row, L), P, R, U, F, w);
        vec4 b = 2 * row + 1 <= 12 ? bp_project(bp_point(state, i, 2 * row + 1, L), P, R, U, F, w) : vec4(0.0);
        return vec4(a.z > 0.0 ? a.xy : vec2(1e4), b.z > 0.0 ? b.xy : vec2(1e4));
    }
    vec4 m = texelFetch(state, ivec2(i, 3), 0);
    if (row == 8) return vec4(m.w, pred ? 1.0 : 0.0, pred ? 0.0 : m.z, L);
    if (row == 9) {
        vec4 a = bp_project(bp_point(state, i, 0, L), P, R, U, F, w);
        return vec4(a.z, a.w, 0.0, 0.0);
    }

    vec4 bb = vec4(1e4, 1e4, -1e4, -1e4);
    if (row == 7) {
        // trail polyline
        for (int k = 0; k <= 12; k++) {
            vec4 a = bp_project(bp_point(state, i, k, L), P, R, U, F, w);
            if (a.z > 0.0) bb = vec4(min(bb.xy, a.xy - a.z), max(bb.zw, a.xy + a.z));
        }
        return bb;
    }
    // body / halo ball
    vec4 c = texelFetch(state, ivec2(i, 0), 0);
    float Hr = L * 1.5;                          // halo radius (the body bound is 0.72 L)
    vec4 X = vec4(bp_dot(c, R), bp_dot(c, U), bp_dot(c, F), max(-bp_dot(c, P), 1.0));
    float sh = sqrt(max(X.w * X.w - 1.0, 1e-10));
    float d = log(X.w + sh);
    if (d < Hr * 1.3) return vec4(-1e4, -1e4, 1e4, 1e4);      // next to the camera: everywhere
    // angular radius of the halo ball: sin(a) = sinh(Hr) / sinh(d)
    float sa = min(sinh(Hr) / sh, 0.999);
    float cz = X.z / sh;                                         // cos of the angle off-axis
    float ca = sqrt(1.0 - sa * sa);
    float cp = cz * ca - sqrt(max(1.0 - cz * cz, 0.0)) * sa;   // cos(off-axis + radius)
    if (cp > 0.02) {
        // gnomonic image of the cone: radial extent foc sin(a) / (cos(b + a) cos(b)) bounds it
        vec2 sc = 1.7 * X.xy / X.z;
        float r = 1.7 * sa / (cp * cz) * 1.1 + 0.004;
        bb = vec4(min(bb.xy, sc - r), max(bb.zw, sc + r));
    } else if (cz > -sa) {
        bb = vec4(-1e4, -1e4, 1e4, 1e4);
    }
    return bb;
}

BoidTiles.customGLSL:
// @node boidTiles
// @title Boid Tile Bins
// @category custom
// @description Screen-tile binning for the boid renderer, into a 960x50 rgba32f / nearest Feedback: the uv screen (aspect 1.6) is cut into 80x50 tiles; each tile has 12 texels of 4 x 24-bit masks (as floats): texels 0..5 = boids whose body / halo box overlaps the tile, 6..11 = boids with a trail segment (capsule) near the tile. The scene then loops only over the set bits of its tile instead of over every boid.
vec4 boidTiles(sampler2D proj, float count, float predators) {
    ivec2 px = ivec2(gl_FragCoord.xy);
    int tx = px.x / 12;
    int slot = px.x - tx * 12;
    bool trail = slot >= 6;
    int texel = trail ? slot - 6 : slot;
    int n = clamp(int(count + 0.5), 0, 512);
    int np = clamp(int(predators + 0.5), 0, 2);
    vec2 lo = vec2(-1.6, -1.0) + vec2(3.2 / 80.0, 2.0 / 50.0) * vec2(float(tx), float(px.y));
    vec2 hi = lo + vec2(3.2 / 80.0, 2.0 / 50.0);
    vec4 res = vec4(0.0);
    for (int ch = 0; ch < 4; ch++) {
        int w = texel * 4 + ch;
        uint bits = 0u;
        for (int b = 0; b < 24; b++) {
            int i = w * 24 + b;
            bool alive = i < n || (i >= 512 && i - 512 < np);
            if (!alive || i >= 514) continue;
            vec4 bb = texelFetch(proj, ivec2(i, trail ? 7 : 10), 0);
            if (!(bb.x <= hi.x && bb.z >= lo.x && bb.y <= hi.y && bb.w >= lo.y)) continue;
            if (trail) {
                // finer: does any trail segment (a capsule of the trail's width) come near the tile?
                float rr = length(hi - lo) * 0.5 + texelFetch(proj, ivec2(i, 9), 0).x;
                vec2 cen = 0.5 * (lo + hi);
                bool hit = false;
                vec2 a = vec2(1e4);
                for (int r = 0; r < 7; r++) {
                    vec4 pp = texelFetch(proj, ivec2(i, r), 0);
                    for (int h = 0; h < 2; h++) {
                        if (2 * r + h > 12) break;
                        vec2 q = h == 0 ? pp.xy : pp.zw;
                        if (a.x < 1e3 && q.x < 1e3) {
                            vec2 ab = q - a;
                            float t = clamp(dot(cen - a, ab) / max(dot(ab, ab), 1e-12), 0.0, 1.0);
                            if (length(cen - a - ab * t) < rr) hit = true;
                        }
                        a = q;
                    }
                }
                if (!hit) continue;
            }
            bits |= 1u << uint(b);
        }
        res[ch] = float(bits);
    }
    return res;
}

BoidBloomSample.customGLSL:
// @node boidBloomSample
// @title Bicubic Bloom Sample
// @category effect
// @description Smooth upsampling of a low-resolution bloom target at the current pixel: cubic B-spline filtering (4 bilinear taps) at the centre plus a ring of 6 more B-spline taps at radius (in texels of the target). No blocky bilinear texels even from a 96x60 target.
vec3 bb_bspline(sampler2D t, vec2 uv, vec2 res) {
    vec2 st = uv * res - 0.5;
    vec2 i = floor(st);
    vec2 f = st - i;
    vec2 f2 = f * f;
    vec2 f3 = f2 * f;
    vec2 w0 = (-f3 + 3.0 * f2 - 3.0 * f + 1.0) / 6.0;
    vec2 w1 = (3.0 * f3 - 6.0 * f2 + 4.0) / 6.0;
    vec2 w2 = (-3.0 * f3 + 3.0 * f2 + 3.0 * f + 1.0) / 6.0;
    vec2 w3 = f3 / 6.0;
    vec2 g0 = w0 + w1;
    vec2 g1 = w2 + w3;
    vec2 h0 = (i - 0.5 + w1 / g0) / res;
    vec2 h1 = (i + 1.5 + w3 / g1) / res;
    return g0.y * (g0.x * texture(t, h0).rgb + g1.x * texture(t, vec2(h1.x, h0.y)).rgb)
         + g1.y * (g0.x * texture(t, vec2(h0.x, h1.y)).rgb + g1.x * texture(t, h1).rgb);
}

vec3 boidBloomSample(sampler2D tex, float radius) {
    vec2 res = vec2(textureSize(tex, 0));
    vec2 uv = gl_FragCoord.xy / u_resolution;
    vec3 acc = bb_bspline(tex, uv, res) * 0.4;
    for (int k = 0; k < 6; k++) {
        float a = 1.0472 * float(k) + 0.3;
        acc += bb_bspline(tex, uv + radius * vec2(cos(a), sin(a)) / res, res) * 0.1;
    }
    return acc;
}

BoidTrails.customGLSL:
// @node boidTrails
// @title Boid Trails
// @category custom
// @description Draws the trails at reduced resolution into an rgba16f Feedback that the scene samples: each trail is a screen polyline of the projected history (geodesic segments are straight in the camera's Klein model), tapered and fading with age, tinted by the boid's hue, fogged by hyperbolic depth. Only boids whose trail touches this pixel's tile are visited. a = depth of the brightest trail (the scene dims trails behind a bird).
// ---- H3 helpers, hyperboloid model: <a,b> = a.x b.x + a.y b.y + a.z b.z - a.w b.w, <p,p> = -1 ----
float bw_dot(vec4 a, vec4 b) {
    return dot(a.xyz, b.xyz) - a.w * b.w;
}

// Back onto the upper sheet of the hyperboloid
vec4 bw_toH(vec4 p) {
    return p / sqrt(max(-bw_dot(p, p), 1e-12));
}

// Tangent projection at p
vec4 bw_tan(vec4 v, vec4 p) {
    return v + bw_dot(v, p) * p;
}

vec4 bw_unit(vec4 v) {
    return v * inversesqrt(max(bw_dot(v, v), 1e-14));
}

float bw_acosh(float c) {
    c = max(c, 1.0);
    return log(c + sqrt(c * c - 1.0));
}

float bw_asinh(float x) {
    return log(x + sqrt(x * x + 1.0));
}

// Log map: tangent vector at p pointing to q, length = d(p, q)
vec4 bw_log(vec4 p, vec4 q) {
    float c = max(-bw_dot(p, q), 1.0);
    float sh = sqrt(c * c - 1.0);
    if (sh < 1e-7) return vec4(0.0);
    return (q - c * p) * (log(c + sh) / sh);
}

// Exponential map: walk the geodesic from p with initial velocity v for |v|
vec4 bw_exp(vec4 p, vec4 v) {
    float n = sqrt(max(bw_dot(v, v), 0.0));
    if (n < 1e-8) return p;
    return cosh(n) * p + (sinh(n) / n) * v;
}

// Parallel transport of w (tangent at q) along the geodesic q -> p
vec4 bw_transport(vec4 w, vec4 q, vec4 p) {
    return w + bw_dot(p, w) / (1.0 - bw_dot(q, p)) * (q + p);
}

// Lorentz-orthogonal complement of three vectors (generalized cross product, index lowered)
vec4 bw_cross4(vec4 a, vec4 b, vec4 c) {
    float x = dot(a.yzw, cross(b.yzw, c.yzw));
    float y = -dot(a.xzw, cross(b.xzw, c.xzw));
    float z = dot(a.xyw, cross(b.xyw, c.xyw));
    float w = -dot(a.xyz, cross(b.xyz, c.xyz));
    return vec4(x, y, z, -w);
}

vec3 bw_hash3(uvec3 v) {
    v = v * 1664525u + 1013904223u;
    v.x += v.y * v.z; v.y += v.z * v.x; v.z += v.x * v.y;
    v ^= v >> 16u;
    v.x += v.y * v.z; v.y += v.z * v.x; v.z += v.x * v.y;
    return vec3(v) * (1.0 / 4294967296.0);
}

// Outward unit normal of face k of the {4,3,5} base cell (Klein cube |x_j| <= A)
vec4 bw_face(int k) {
    const float A = 0.48586827;
    int j = k / 2;
    float s = (k - j * 2 == 0) ? 1.0 : -1.0;
    vec3 e = j == 0 ? vec3(1.0, 0.0, 0.0) : (j == 1 ? vec3(0.0, 1.0, 0.0) : vec3(0.0, 0.0, 1.0));
    return vec4(e * s, A) * 1.1441228;   // 1 / sqrt(1 - A^2)
}

// Three-colour cyclic palette
vec3 bw_pal(float t, vec3 a, vec3 b, vec3 c) {
    t = fract(t) * 3.0;
    if (t < 1.0) return mix(a, b, smoothstep(0.0, 1.0, t));
    if (t < 2.0) return mix(b, c, smoothstep(1.0, 2.0, t));
    return mix(c, a, smoothstep(2.0, 3.0, t));
}


vec4 boidTrails(vec2 uv, sampler2D state, sampler2D proj, sampler2D tiles, float count, float predators, float fog, vec3 colorA, vec3 colorB, vec3 colorC, vec3 predatorColor) {
    vec4 g0 = texelFetch(state, ivec2(514, 0), 0);
    float pxs = 2.0 / u_resolution.y;
    int n = clamp(int(count + 0.5), 0, 512);
    int np = clamp(int(predators + 0.5), 0, 2);
    ivec2 tile = ivec2(clamp(floor((uv + vec2(1.6, 1.0)) / vec2(3.2, 2.0) * vec2(80.0, 50.0)), vec2(0.0), vec2(80.0 - 1.0, 50.0 - 1.0)));
    int nw = (n + 95) / 96;
    float trailGlow = 1.0;
    // ---- trails: screen polylines of geodesic segments (exact projection of the Klein lines)
    float frac = clamp(g0.x, 0.0, 1.0);          // progress to the next history shift
    vec3 trails = vec3(0.0);
    float bestLum = 0.0;
    float depth = 1e4;
    if (trailGlow > 0.0) {
        int budget = 48;
        for (int t = 0; t < 6; t++) {
            if (t >= nw && !(t == 5 && np > 0)) continue;
            vec4 wv = texelFetch(tiles, ivec2(tile.x * 12 + 6 + t, tile.y), 0);
            for (int ch = 0; ch < 4; ch++) {
            uint bits = uint(wv[ch]);
            while (bits != 0u && budget > 0) {
            int i = (t * 4 + ch) * 24 + int(log2(float(bits & (~bits + 1u))) + 0.5);
            bits &= bits - 1u;
            vec4 bb = texelFetch(proj, ivec2(i, 7), 0);
            if (uv.x < bb.x || uv.y < bb.y || uv.x > bb.z || uv.y > bb.w) continue;
            budget--;
            vec4 inf = texelFetch(proj, ivec2(i, 8), 0);
            vec4 hd = texelFetch(proj, ivec2(i, 9), 0);
            if (hd.x <= 0.0) continue;
            float best = 0.0;
            float bAge = 0.0;
            vec2 a = vec2(1e4);
            float ageA = 0.0;
            for (int r = 0; r < 7; r++) {
                vec4 pp = texelFetch(proj, ivec2(i, r), 0);
                for (int h = 0; h < 2; h++) {
                    int k = 2 * r + h;
                    if (k > 12) break;
                    vec2 b = h == 0 ? pp.xy : pp.zw;
                    float ageB = k == 0 ? 0.0 : (float(k - 1) + frac) / 12.0;   // point k = history k - 1
                    if (k > 0 && a.x < 1e3 && b.x < 1e3) {
                        vec2 ab = b - a;
                        float hseg = clamp(dot(uv - a, ab) / max(dot(ab, ab), 1e-12), 0.0, 1.0);
                        vec2 dv = uv - a - ab * hseg;
                        float age = mix(ageA, ageB, hseg);
                        float hw = hd.x * (1.0 - 0.75 * age);
                        float w = max(hw, pxs * 0.75);
                        float I = exp(-dot(dv, dv) / (w * w) * 1.6) * (hw / w) * (1.0 - age) * (1.0 - age);
                        if (I > best) { best = I; bAge = age; }
                    }
                    a = b;
                    ageA = ageB;
                }
            }
            vec3 tc = inf.y > 0.5 ? predatorColor * 1.4 : bw_pal(inf.x + 0.15 * bAge, colorA, colorB, colorC) * (1.0 + inf.z);
            vec3 add = tc * best * exp(-hd.y * fog);
            float ad = dot(add, vec3(0.3, 0.5, 0.2));
            if (ad > bestLum) { bestLum = ad; depth = hd.y; }
            trails += add;
            }
            }
        }
    }
    return vec4(trails, depth);
}
